/**
 * Zod transform factory for motion model inputs.
 *
 * Returns a function that accepts our internal camelCase format
 * (numeric duration, imageUrl, aspectRatio) and produces the API's
 * snake_case body with correctly-typed duration values, validated
 * against the generated Zod schema.
 *
 * All formatting rules are derived from the JSON Schema (generated by
 * @hey-api/schemas) — no Zod introspection needed.
 *
 * Each function is closed over one schema. `MOTION_TRANSFORMS` is a map of
 * those functions, annotated per endpoint id, so a generic id returns that
 * endpoint's output instead of a union Zod collapses.
 */

import { z } from 'zod';

import type { MotionJSONSchema } from './endpoint-map';

import { assertPromptWithinHardLimit } from '@/models/prompt-length';

// ---------------------------------------------------------------------------
// JSON Schema readers
// ---------------------------------------------------------------------------

type JSONProp = Record<string, unknown>;

/** Unwrap anyOf wrapper to find a variant matching a key. */
function unwrapAnyOf(prop: JSONProp, key: string): JSONProp | undefined {
  if (key in prop) return prop;
  if ('anyOf' in prop && Array.isArray(prop.anyOf)) {
    return prop.anyOf.find((s) => key in s);
  }
  return undefined;
}

/** Extract valid duration values from the JSON Schema duration property. */
export function getDurationValues<T extends MotionJSONSchema>(
  schema: T
): (string | number)[] {
  const props = schema.properties;
  if (!('duration' in props)) return [];
  const dur = props.duration as JSONProp;

  const withEnum = unwrapAnyOf(dur, 'enum');
  if (withEnum && Array.isArray(withEnum.enum))
    return withEnum.enum.filter((v) => !Number.isNaN(numericOf(v)));

  const withRange = unwrapAnyOf(dur, 'minimum');
  if (withRange) {
    // Whole seconds inside the range: a fractional bound (H3 Max takes
    // 0.92–15) must not shift every step onto 0.92, 1.92, …
    const min = Math.ceil(Number(withRange.minimum));
    const max = Math.floor(Number(withRange.maximum));
    return Array.from({ length: max - min + 1 }, (_, i) => min + i);
  }

  return [];
}

/**
 * Extract maxLength from the prompt property, handling anyOf wrappers.
 *
 * Present = fal enforces it, so it is a hard ceiling (#1754). Absent — every
 * Seedance endpoint — means there is no cap to enforce.
 */
function getPromptMaxLength(schema: MotionJSONSchema): number | undefined {
  const props = schema.properties;
  if (!('prompt' in props)) return undefined;
  const max = unwrapAnyOf(props.prompt, 'maxLength')?.maxLength;
  return typeof max === 'number' ? max : undefined;
}

/**
 * Find the image URL field name (start_image_url or image_url).
 *
 * Exported as {@link hasStartFrameField} so callers can ask whether an
 * endpoint takes a real start frame without duplicating the answer into a
 * config that could then disagree with the schema.
 */
function getImageUrlField(schema: MotionJSONSchema): string | undefined {
  const props = schema.properties;
  if ('start_image_url' in props) return 'start_image_url';
  if ('image_url' in props) return 'image_url';
  return undefined;
}

/**
 * Does this reference endpoint pin a still in `start_image_url`?
 *
 * Among the reference-to-video endpoints only Kling O3 and Kling 4 have one.
 * H3 Max's r2v also has a first-frame `image_url`, deliberately not pinned:
 * its still rides `reference_image_urls` as Image 1, which works, and a
 * pinned still would leave an audio-only shot with no image reference, which
 * fal refuses.
 */
export function hasStartFrameField(schema: MotionJSONSchema): boolean {
  return getImageUrlField(schema) === 'start_image_url';
}

// ---------------------------------------------------------------------------
// Transform helpers
// ---------------------------------------------------------------------------

const zMotionInput = z.looseObject({
  prompt: z.string(),
  duration: z.number().optional(),
  imageUrl: z.string().optional(),
  aspectRatio: z.string().optional(),
});

export function numericOf(v: string | number): number {
  return typeof v === 'number' ? v : parseFloat(v);
}

export function snapTo(
  n: number,
  values: readonly (string | number)[]
): string | number {
  const numeric = values.filter((v) => !Number.isNaN(numericOf(v)));
  return numeric.reduce((prev, curr) =>
    Math.abs(numericOf(curr) - n) < Math.abs(numericOf(prev) - n) ? curr : prev
  );
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Build a parser from an API schema + its JSON Schema metadata.
 *
 * Accepts camelCase input (prompt, duration, imageUrl, aspectRatio),
 * transforms to the API's snake_case format, and validates. Duration
 * values and the image field are read once, when the parser is built.
 */
export function motionTransform<T extends z.ZodObject<z.ZodRawShape>>(
  apiSchema: T,
  jsonSchema: MotionJSONSchema
): (input: unknown) => z.output<T> {
  const durationValues = getDurationValues(jsonSchema);
  const imageUrlField = getImageUrlField(jsonSchema);
  const maxPromptLength = getPromptMaxLength(jsonSchema);

  return (input) => {
    const { imageUrl, aspectRatio, duration, prompt, ...rest } =
      zMotionInput.parse(input);
    // A `maxLength` in fal's own schema is a ceiling fal enforces, so this is
    // the one place a prompt is refused rather than sent (#1754). It used to
    // be cut down to fit, which shipped a prompt nobody had seen; now the
    // motion rescue shortens it into a visible prompt version instead.
    assertPromptWithinHardLimit(prompt, maxPromptLength);
    const raw = {
      ...rest,
      prompt,
      ...(imageUrl && imageUrlField && { [imageUrlField]: imageUrl }),
      ...(aspectRatio && { aspect_ratio: aspectRatio }),
      ...(duration !== undefined &&
        durationValues.length > 0 && {
          duration: snapTo(duration, durationValues),
        }),
    };
    return apiSchema.parse(raw);
  };
}
